    { sp:'Claire', fr:'Alors prends-le quand même.', vi:'Thế thì cứ lấy đi.' },
    { sp:'Quân', fr:'C\'est un compromis, mais je le signe demain.', vi:'Đây là một sự thoả hiệp, nhưng mai tớ ký.' }
